1019: void amdgpu_gmc_noretry_set(struct amdgpu_device *adev)
1020: {
1021: 	struct amdgpu_gmc *gmc = &adev->gmc;
1022: 	uint32_t gc_ver = amdgpu_ip_version(adev, GC_HWIP, 0);
1023: 	bool noretry_default = (gc_ver == IP_VERSION(9, 0, 1) ||
1024: 				gc_ver == IP_VERSION(9, 4, 0) ||
1025: 				gc_ver == IP_VERSION(9, 4, 1) ||
1026: 				gc_ver == IP_VERSION(9, 4, 2) ||
1027: 				gc_ver == IP_VERSION(9, 4, 3) ||
1028: 				gc_ver == IP_VERSION(9, 4, 4) ||
1029: 				gc_ver == IP_VERSION(9, 5, 0) ||
1030: 				gc_ver >= IP_VERSION(10, 1, 0));
1031: 
1032: 	if (!amdgpu_sriov_xnack_support(adev))
1033: 		gmc->noretry = 1;
1034: 	else
1035: 		gmc->noretry = (amdgpu_noretry == -1) ? noretry_default : amdgpu_noretry;
1036: 
1037: 	/* keep this for kfd test fail */
1038: 	switch (adev->asic_type) {
1039: 	case CHIP_VEGA10:
1040: 	case CHIP_NAVI10:
1041: 	case CHIP_NAVI14:
1042: 	case CHIP_SIENNA_CICHLID:
1043: 	case CHIP_NAVY_FLOUNDER:
1044: 	case CHIP_DIMGREY_CAVEFISH:
1045: 		/*
1046: 		 * noretry = 0 will cause kfd page fault tests fail
1047: 		 * for some ASICs, so set default to 1 for these ASICs.
1048: 		 */
1049: 		if (amdgpu_noretry == -1)
1050: 			gmc->noretry = 1;
1051: 		else
1052: 			gmc->noretry = amdgpu_noretry;
1053: 		break;
1054: 	default:
1055: 		break;
1056: 	}

