1993: static void gfx_v12_1_xcc_xnack_set_chicken_bits(struct amdgpu_device *adev, int xcc_id)
1994: {
1995: 	/* NOTE: COMPRESSION_ENABLE is used a chicken bit to enable/disable xcc xnack */
1996: 	mutex_lock(&adev->srbm_mutex);
1997: 	if (!adev->gmc.noretry) {
1998: 		WREG32_FIELD15_PREREG(GC, GET_INST(GC, xcc_id),
1999: 				      TCP_PERFCOUNTER_FILTER, COMPRESSION_ENABLE, 0x1);
2000: 	} else
2001: 		WREG32_FIELD15_PREREG(GC, GET_INST(GC, xcc_id),
2002: 				      TCP_PERFCOUNTER_FILTER, COMPRESSION_ENABLE, 0x0);
2003: 	mutex_unlock(&adev->srbm_mutex);
2004: }

