1674: bool kfd_process_xnack_mode(struct kfd_process *p, bool supported)
1675: {
1676: 	int i;
1677: 
1678: 	/* On most GFXv9 GPUs, the retry mode in the SQ must match the
1679: 	 * boot time retry setting. Mixing processes with different
1680: 	 * XNACK/retry settings can hang the GPU.
1681: 	 *
1682: 	 * Different GPUs can have different noretry settings depending
1683: 	 * on HW bugs or limitations. We need to find at least one
1684: 	 * XNACK mode for this process that's compatible with all GPUs.
1685: 	 * Fortunately GPUs with retry enabled (noretry=0) can run code
1686: 	 * built for XNACK-off. On GFXv9 it may perform slower.
1687: 	 *
1688: 	 * Therefore applications built for XNACK-off can always be
1689: 	 * supported and will be our fallback if any GPU does not
1690: 	 * support retry.
1691: 	 */
1692: 	for (i = 0; i < p->n_pdds; i++) {
1693: 		struct kfd_node *dev = p->pdds[i]->dev;
1694: 
1695: 		/* Only consider GFXv9 and higher GPUs. Older GPUs don't
1696: 		 * support the SVM APIs and don't need to be considered
1697: 		 * for the XNACK mode selection.
1698: 		 */
1699: 		if (!KFD_IS_SOC15(dev))
1700: 			continue;
1701: 		/* Aldebaran can always support XNACK because it can support
1702: 		 * per-process XNACK mode selection. But let the dev->noretry
1703: 		 * setting still influence the default XNACK mode.
1704: 		 */
1705: 		if (supported && KFD_SUPPORT_XNACK_PER_PROCESS(dev)) {
1706: 			if (!amdgpu_sriov_xnack_support(dev->kfd->adev)) {
1707: 				pr_debug("SRIOV platform xnack not supported\n");
1708: 				return false;
1709: 			}
1710: 			continue;
1711: 		}
1712: 
1713: 		/* GFXv10 and later GPUs do not support shader preemption
1714: 		 * during page faults. This can lead to poor QoS for queue
1715: 		 * management and memory-manager-related preemptions or
1716: 		 * even deadlocks.
1717: 		 */
1718: 		if (KFD_GC_VERSION(dev) >= IP_VERSION(10, 1, 1) &&
1719: 		    KFD_GC_VERSION(dev) < IP_VERSION(12, 1, 0))
1720: 			return false;
1721: 
1722: 		if (dev->kfd->noretry)
1723: 			return false;
1724: 	}
1725: 
1726: 	return true;
1727: }

