51: static int update_qpd_v12_1(struct device_queue_manager *dqm,
52: 			 struct qcm_process_device *qpd)
53: {
54: 	struct kfd_process_device *pdd;
55: 	struct amdgpu_device *adev = dqm->dev->adev;
