61: 
62: 	/* check if sh_mem_config register already configured */
63: 	if (qpd->sh_mem_config == 0) {
64: 		qpd->sh_mem_config =
65: 			(SH_MEM_ALIGNMENT_MODE_UNALIGNED <<
66: 				SH_MEM_CONFIG__ALIGNMENT_MODE__SHIFT) |
67: 			(3 << SH_MEM_CONFIG__INITIAL_INST_PREFETCH__SHIFT);
