73: 	}
74: 
75: 	xnack_enabled = KFD_SUPPORT_XNACK_PER_PROCESS(dqm->dev) ?
76: 			pdd->process->xnack_enabled :
77: 			!pdd->dev->kfd->noretry;
78: 
79: 	if (!xnack_enabled) {
80: 		qpd->sh_mem_config |= 1 << SH_MEM_CONFIG__RETRY_DISABLE__SHIFT;
81: 		qpd->vm_cntx_cntl &=
82: 			~(1 << GCVM_CONTEXT0_CNTL__RETRY_PERMISSION_OR_INVALID_PAGE_FAULT__SHIFT);
83: 	} else {
84: 		qpd->sh_mem_config &= ~(1 << SH_MEM_CONFIG__RETRY_DISABLE__SHIFT);
85: 		qpd->vm_cntx_cntl |=
86: 			(1 << GCVM_CONTEXT0_CNTL__RETRY_PERMISSION_OR_INVALID_PAGE_FAULT__SHIFT);
87: 	}
