245: 		return -EIO;
246: 
247: 	memset(&queue_input, 0x0, sizeof(struct mes_add_queue_input));
248: 	queue_input.process_id = pdd->pasid;
249: 	queue_input.page_table_base_addr =  qpd->page_table_base;
250: 	queue_input.process_va_start = 0;
251: 	queue_input.process_va_end = adev->vm_manager.max_pfn - 1;
252: 	/* MES unit for quantum is 100ns */
253: 	queue_input.process_quantum = KFD_MES_PROCESS_QUANTUM;  /* Equivalent to 10ms. */
254: 	queue_input.process_context_addr = pdd->proc_ctx_gpu_addr;
255: 	queue_input.gang_quantum = KFD_MES_GANG_QUANTUM; /* Equivalent to 1ms */
256: 	queue_input.gang_context_addr = q->gang_ctx_gpu_addr;
257: 	queue_input.inprocess_gang_priority = q->properties.priority;
258: 	queue_input.gang_global_priority_level =
259: 					AMDGPU_MES_PRIORITY_LEVEL_NORMAL;
260: 	queue_input.doorbell_offset = q->properties.doorbell_off;
261: 	queue_input.mqd_addr = q->gart_mqd_addr;
262: 	queue_input.wptr_addr = (uint64_t)q->properties.write_ptr;
263: 
264: 	wptr_addr_off = (uint64_t)q->properties.write_ptr & (PAGE_SIZE - 1);
265: 	queue_input.wptr_mc_addr = amdgpu_bo_gpu_offset(q->properties.wptr_bo) + wptr_addr_off;
266: 
267: 	queue_input.is_kfd_process = 1;
268: 	queue_input.is_aql_queue = (q->properties.format == KFD_QUEUE_FORMAT_AQL);
269: 	queue_input.queue_size = q->properties.queue_size >> 2;
270: 
271: 	queue_input.paging = false;
272: 	queue_input.tba_addr = qpd->tba_addr;
273: 	queue_input.tma_addr = qpd->tma_addr;
274: 	queue_input.trap_en = !kfd_dbg_has_cwsr_workaround(q->device);
275: 	queue_input.skip_process_ctx_clear =
276: 		qpd->pqm->process->runtime_info.runtime_state == DEBUG_RUNTIME_STATE_ENABLED &&
277: 						(qpd->pqm->process->debug_trap_enabled ||
278: 						 kfd_dbg_has_ttmps_always_setup(q->device));
279: 
280: 	queue_type = convert_to_amdgpu_ring_type(q->properties.type);
281: 	if (queue_type < 0) {
282: 		dev_err(adev->dev, "Queue type not supported with MES, queue:%d\n",
283: 			q->properties.type);
284: 		up_read(&adev->reset_domain->sem);
285: 		return -EINVAL;
286: 	}
287: 	queue_input.queue_type = (uint32_t)queue_type;
288: 
289: 	queue_input.exclusively_scheduled = q->properties.is_gws;
290: 	queue_input.sh_mem_config_data = qpd->sh_mem_config;
291: 	queue_input.vm_cntx_cntl = qpd->vm_cntx_cntl;
292: 	queue_input.xcc_id = ffs(dqm->dev->xcc_mask) - 1;
293: 
294: 	amdgpu_mes_lock(&adev->mes);
295: 	r = adev->mes.funcs->add_hw_queue(&adev->mes, &queue_input);
296: 	amdgpu_mes_unlock(&adev->mes);
297: 	up_read(&adev->reset_domain->sem);
298: 	if (r) {
299: 		dev_err(adev->dev, "failed to add hardware queue to MES, doorbell=0x%x\n",
300: 			q->properties.doorbell_off);
301: 		dev_err(adev->dev, "MES might be in unrecoverable state, issue a GPU reset\n");
302: 		kfd_hws_hang(dqm);
303: 	}
304: 
305: 	return r;

